inline bool ProfileExists(std::uint8_t localRace, std::uint8_t retailRace, std::uint8_t sex)
{
    return std::any_of(Profiles.begin(), Profiles.end(), [=](Profile const& profile)
    {
        return profile.localRace == localRace && profile.retailRace == retailRace && profile.sex == sex;
    });
}

inline bool HasLocalRace(std::uint8_t localRace, std::uint8_t sex)
{
    return std::any_of(Profiles.begin(), Profiles.end(), [=](Profile const& profile)
    {
        return profile.localRace == localRace && profile.sex == sex;
    });
}

inline std::uint8_t ExpectedOptionCount(std::uint8_t localRace, std::uint8_t retailRace, std::uint8_t sex)
{
    auto const found = std::find_if(Profiles.begin(), Profiles.end(), [=](Profile const& profile)
    {
        return profile.localRace == localRace && profile.retailRace == retailRace && profile.sex == sex;
    });
    return found == Profiles.end() ? 0 : found->optionCount;
}

inline bool ChoiceExists(std::uint8_t localRace, std::uint8_t retailRace, std::uint8_t sex,
    std::uint32_t option, std::uint32_t choice)
{
    return std::any_of(Choices.begin(), Choices.end(), [=](Choice const& item)
    {
        return item.localRace == localRace && item.retailRace == retailRace && item.sex == sex
            && item.option == option && item.choice == choice;
    });
}
